1	package overlay
2	
3	import (
4		"reflect"
5		"regexp"
6		"strings"
7		"testing"
8	
9		"github.com/charmbracelet/lipgloss"
10		"github.com/charmbracelet/x/ansi"
11	)
12	
13	const (
14		reset     = "\x1b[0m"
15		baseSGR   = "\x1b[1;38;2;166;227;161;48;2;30;30;46m"
16		boxSGR    = "\x1b[38;2;243;139;168m"
17		underline = "\x1b[4m"
18	)
19	
20	var widths = []int{40, 60, 80, 120}
21	
22	// completeCSI matches a well-formed CSI sequence; anything else starting with
23	// ESC is a cut sequence.
24	var completeCSI = regexp.MustCompile(`\x1b\[[0-9;:]*[A-Za-z]`)
25	
26	// assertNoOrphan fails when s holds an escape sequence that is not complete, or
27	// a fragment of one left behind once the complete ones are removed.
28	func assertNoOrphan(t *testing.T, s string) {
29		t.Helper()
30		rest := completeCSI.ReplaceAllString(s, "")
31		if strings.Contains(rest, "\x1b") {
32			t.Errorf("incomplete escape sequence in %q", s)
33		}
34		plain := ansi.Strip(s)
35		if strings.Contains(plain, "[38;2") || strings.Contains(plain, "[0m") || strings.Contains(plain, "\x1b") {
36			t.Errorf("orphan escape fragment left after Strip: %q", plain)
37		}
38	}
39	
40	func assertWidth(t *testing.T, s string, width int) {
41		t.Helper()
42		if got := lipgloss.Width(s); got != width {
43			t.Errorf("width = %d, want %d (line %q)", got, width, s)
44		}
45	}
46	
47	func TestSplicePlain(t *testing.T) {
48		for _, width := range widths {
49			tests := []struct {
50				name string
51				x    int
52				box  string
53			}{
54				{"middle", 10, "[ palette ]"},
55				{"left edge", 0, "[ palette ]"},
56				{"right edge", width - 11, "[ palette ]"},
57				{"whole line", 0, strings.Repeat("#", width)},
58			}
59			for _, tc := range tests {
60				t.Run(tc.name, func(t *testing.T) {
61					line := strings.Repeat(".", width)
62					got, ok := Splice(line, tc.box, tc.x, width)
63					if !ok {
64						t.Fatalf("Splice reported failure for a box that fits")
65					}
66					bw := lipgloss.Width(tc.box)
67					want := line[:tc.x] + tc.box + line[tc.x+bw:]
68					if ansi.Strip(got) != want {
69						t.Errorf("stripped = %q, want %q", ansi.Strip(got), want)
70					}
71					assertWidth(t, got, width)
72					assertNoOrphan(t, got)
73				})
74			}
75		}
76	}
77	
78	func TestSpliceStyledBase(t *testing.T) {
79		tests := []struct {
80			name string
81			line func(width int) string
82			// restored is the prefix the right part must open with after the box.
83			restored string
84		}{
85			{
86				name:     "one segment spanning the line",
87				line:     func(w int) string { return baseSGR + strings.Repeat("a", w) + reset },
88				restored: baseSGR,
89			},
90			{
91				name: "underlined base",
92				line: func(w int) string {
93					return underline + strings.Repeat("a", w) + reset
94				},
95				restored: underline,
96			},
97			{
98				name: "style changes before the cut",
99				line: func(w int) string {
100					return baseSGR + strings.Repeat("a", 5) + boxSGR + strings.Repeat("b", w-5) + reset
101				},
102				restored: boxSGR,
103			},
104		}
105		for _, width := range widths {
106			for _, tc := range tests {
107				t.Run(tc.name, func(t *testing.T) {
108					box := boxSGR + "BOX" + reset
109					got, ok := Splice(tc.line(width), box, 10, width)
110					if !ok {
111						t.Fatal("Splice reported failure")
112					}
113					assertWidth(t, got, width)
114					assertNoOrphan(t, got)
115	
116					plain := ansi.Strip(got)
117					if plain[10:13] != "BOX" {
118						t.Errorf("box not at column 10: %q", plain)
119					}
120					_, after, found := strings.Cut(got, "BOX")
121					if !found {
122						t.Fatalf("box text missing from %q", got)
123					}
124					// The right part must reopen the style the base had at the cut,
125					// after a reset that closes the box's own.
126					if !strings.Contains(after, reset+tc.restored) {
127						t.Errorf("right part does not restore %q after a reset: %q", tc.restored, after)
128					}
129				})
130			}
131		}
132	}
133	
134	func TestSpliceCutInsideStyledRun(t *testing.T) {
135		// A long SGR sequence sits exactly at the cut columns: it must not be split.
136		for _, x := range []int{4, 5, 6, 9, 10, 11} {
137			line := "aaaaa" + baseSGR + "bbbbbbbbbb" + reset + strings.Repeat("c", 30)
138			got, ok := Splice(line, "XY", x, 45)
139			if !ok {
140				t.Fatalf("x=%d: failure", x)
141			}
142			assertWidth(t, got, 45)
143			assertNoOrphan(t, got)
144		}
145	}
146	
147	func TestSpliceShortOrEmptyBase(t *testing.T) {
148		for _, width := range widths {
149			for _, line := range []string{"", "short", baseSGR + "short" + reset} {
150				got, ok := Splice(line, "BOX", 20, width)
151				if !ok {
152					t.Fatalf("width %d, line %q: failure", width, line)
153				}
154				assertWidth(t, got, width)
155				assertNoOrphan(t, got)
156				if ansi.Strip(got)[20:23] != "BOX" {
157					t.Errorf("box not at column 20: %q", ansi.Strip(got))
158				}
159			}
160		}
161	}
162	
163	func TestSpliceWideRuneAtTheEdges(t *testing.T) {
164		// 20 cells: ten double-width runes, each starting on an even column.
165		const wide = "世世世世世世世世世世"
166		t.Run("left cut straddles a wide rune", func(t *testing.T) {
167			got, ok := Splice(wide, "AB", 3, 20)
168			if !ok {
169				t.Fatal("expected a compensated splice, got failure")
170			}
171			assertWidth(t, got, 20)
172			assertNoOrphan(t, got)
173			plain := ansi.Strip(got)
174			if !strings.HasPrefix(plain, "世 AB") {
175				t.Errorf("left part not compensated by one space: %q", plain)
176			}
177		})
178		t.Run("right cut straddles a wide rune", func(t *testing.T) {
179			// box covers columns 2..4, so the rune on columns 4-5 is cut at its start.
180			got, ok := Splice(wide, "ABC", 2, 20)
181			if !ok {
182				t.Fatal("expected a compensated splice, got failure")
183			}
184			assertWidth(t, got, 20)
185			assertNoOrphan(t, got)
186			plain := ansi.Strip(got)
187			if !strings.HasPrefix(plain, "世ABC ") {
188				t.Errorf("right part not prefixed by one space: %q", plain)
189			}
190		})
191		t.Run("both edges at once", func(t *testing.T) {
192			got, ok := Splice(wide, "ABC", 3, 20)
193			if !ok {
194				t.Fatal("failure")
195			}
196			assertWidth(t, got, 20)
197			assertNoOrphan(t, got)
198		})
199		t.Run("styled wide base", func(t *testing.T) {
200			got, ok := Splice(baseSGR+wide+reset, "AB", 3, 20)
201			if !ok {
202				t.Fatal("failure")
203			}
204			assertWidth(t, got, 20)
205			assertNoOrphan(t, got)
206		})
